+// React-style component structure
+class ContactForm {
+    constructor() {
+        this.state = {
+            fullName: '',
+            email: '',
+            phoneNumber: '',
+            touched: {},
+            submitted: false,
+            success: false
+        };
+    }
+
+    validate() {
+        const errors = {};
+
+        if (!this.state.fullName.trim()) {
+            errors.fullName = 'Full name is required';
+        }
+
+        if (!this.state.email.trim()) {
+            errors.email = 'Email address is required';
+        } else if (!this.isValidEmail(this.state.email)) {
+            errors.email = 'Please enter a valid email address';
+        }
+
+        if (this.state.phoneNumber.trim() && !this.isValidPhone(this.state.phoneNumber)) {
+            errors.phoneNumber = 'Please enter a valid phone number';
+        }
+
+        return errors;
+    }
+
+    isValidEmail(email) {
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        return emailRegex.test(email);
+    }
+
+    isValidPhone(phone) {
+        const phoneRegex = /^[\d\s\-\(\)\+\.]+$/;
+        return phoneRegex.test(phone) && phone.replace(/\D/g, '').length >= 10;
+    }
+
+    handleInputChange(field, value) {
+        this.state[field] = value;
+        this.render();
+    }
+
+    handleInputBlur(field) {
+        this.state.touched[field] = true;
+        this.render();
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+        this.state.submitted = true;
+
+        const errors = this.validate();
+        if (Object.keys(errors).length === 0) {
+            this.state.success = true;
+            this.state.fullName = '';
+            this.state.email = '';
+            this.state.phoneNumber = '';
+            this.state.touched = {};
+            this.state.submitted = false;
+
+            setTimeout(() => {
+                this.state.success = false;
+                this.render();
+            }, 5000);
+
+            this.render();
+            return;
+        }
+
+        this.render();
+    }
+
+    render() {
+        const root = document.getElementById('root');
+        const errors = this.validate();
+
+        root.innerHTML = `
+            <div class="contact-form-container">
+                <div class="form-header">
+                    <h1>Contact Support</h1>
+                    <p>We're here to help. Send us a message and we'll respond as soon as possible.</p>
+                </div>
+
+                ${this.state.success ? `
+                    <div class="success-message">
+                        Thank you! We've received your message and will get back to you shortly.
+                    </div>
+                ` : ''}
+
+                <form class="form" id="contact-form">
+                    <div class="form-field">
+                        <label for="full-name">
+                            Full Name
+                            <span class="required">*</span>
+                        </label>
+                        <input
+                            type="text"
+                            id="full-name"
+                            placeholder="John Doe"
+                            value="${this.escapeHtml(this.state.fullName)}"
+                        >
+                        ${(this.state.touched.fullName || this.state.submitted) && errors.fullName ? `
+                            <div class="error-message show">${errors.fullName}</div>
+                        ` : ''}
+                    </div>
+
+                    <div class="form-field">
+                        <label for="email">
+                            Email Address
+                            <span class="required">*</span>
+                        </label>
+                        <input
+                            type="email"
+                            id="email"
+                            placeholder="john@example.com"
+                            value="${this.escapeHtml(this.state.email)}"
+                        >
+                        ${(this.state.touched.email || this.state.submitted) && errors.email ? `
+                            <div class="error-message show">${errors.email}</div>
+                        ` : ''}
+                    </div>
+
+                    <div class="form-field">
+                        <label for="phone-number">
+                            Phone Number
+                        </label>
+                        <input
+                            type="tel"
+                            id="phone-number"
+                            placeholder="+1 (555) 123-4567"
+                            value="${this.escapeHtml(this.state.phoneNumber)}"
+                        >
+                        <div class="helper-text">
+                            Enter your phone number in any common format (e.g., +1 (555) 123-4567 or 555-123-4567). Optional, but helps us reach you faster.
+                        </div>
+                        ${(this.state.touched.phoneNumber || this.state.submitted) && errors.phoneNumber ? `
+                            <div class="error-message show">${errors.phoneNumber}</div>
+                        ` : ''}
+                    </div>
+
+                    <button type="submit" class="submit-button">Send Message</button>
+                </form>
+            </div>
+        `;
+
+        this.attachEventListeners();
+    }
+
+    attachEventListeners() {
+        const form = document.getElementById('contact-form');
+        const fullNameInput = document.getElementById('full-name');
+        const emailInput = document.getElementById('email');
+        const phoneInput = document.getElementById('phone-number');
+
+        fullNameInput.addEventListener('input', (e) => this.handleInputChange('fullName', e.target.value));
+        fullNameInput.addEventListener('blur', () => this.handleInputBlur('fullName'));
+
+        emailInput.addEventListener('input', (e) => this.handleInputChange('email', e.target.value));
+        emailInput.addEventListener('blur', () => this.handleInputBlur('email'));
+
+        phoneInput.addEventListener('input', (e) => this.handleInputChange('phoneNumber', e.target.value));
+        phoneInput.addEventListener('blur', () => this.handleInputBlur('phoneNumber'));
+
+        form.addEventListener('submit', (e) => this.handleSubmit(e));
+    }
+
+    escapeHtml(text) {
+        const map = {
+            '&': '&amp;',
+            '<': '&lt;',
+            '>': '&gt;',
+            '"': '&quot;',
+            "'": '&#039;'
+        };
+        return text.replace(/[&<>"']/g, (m) => map[m]);
+    }
+}
+
+// Initialize the app
+document.addEventListener('DOMContentLoaded', () => {
+    const app = new ContactForm();
+    app.render();
+});
+
